import{c as a,Q as r,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"From Failed Trajectories to Reliable LLM Agents: Diagnosing and Repairing Harness Flaws","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.06324","title":"From Failed Trajectories to Reliable LLM Agents: Diagnosing and Repairing Harness Flaws","archived_date":"2026-06-14T00:00:00.000Z","arxiv_id":2606.06324,"authors":["Mengzhuo Chen","Junjie Wang","Zhe Liu","Yawen Wang","Qing Wang"],"pdf_path":"pdfs/2606.06324.pdf","published_date":"2026-06-04T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-04-harnessfix-diagnosing-repairing-harness-flaws-2606-06324.md","filePath":"research/papers/2026-06-04-harnessfix-diagnosing-repairing-harness-flaws-2606-06324.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-06-04-harnessfix-diagnosing-repairing-harness-flaws-2606-06324.md"};function t(o,e,l,c,d,g){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="from-failed-trajectories-to-reliable-llm-agents-diagnosing-and-repairing-harness-flaws" tabindex="-1">From Failed Trajectories to Reliable LLM Agents: Diagnosing and Repairing Harness Flaws <a class="header-anchor" href="#from-failed-trajectories-to-reliable-llm-agents-diagnosing-and-repairing-harness-flaws" aria-label="Permalink to &quot;From Failed Trajectories to Reliable LLM Agents: Diagnosing and Repairing Harness Flaws&quot;">​</a></h1><p><strong>Authors</strong>: Mengzhuo Chen, Junjie Wang, Zhe Liu, Yawen Wang, Qing Wang <strong>Published</strong>: June 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.06324" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.06324</a><strong>arXiv ID</strong>: 2606.06324 <strong>Categories</strong>: Software Engineering (cs.SE); Multiagent Systems (cs.MA) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.06324" target="_blank" rel="noreferrer">research/papers/pdfs/2606.06324.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>LLM-based agents increasingly rely on harnesses that provide execution environments, tool interfaces, context, lifecycle orchestration, observability, verification, and governance. Existing self-improving agents and automatic harness evolution methods mainly improve agents through runtime supervision, prompt optimization, workflow search, or harness modification based on final outcomes. However, they often fail to diagnose where the responsible evidence lies in failed trajectories and which harness layer causes the unreliable behavior, resulting in broad, indirect, or poorly scoped changes. This paper proposes HarnessFix, a trace-guided framework for diagnosing agent failures and repairing agent harnesses. HarnessFix compiles raw execution traces and harness code into a Harness-aware Trace Intermediate Representation (HTIR), which normalizes fragmented trajectory evidence and captures step-level provenance and control-flow relations. It then attributes failures to responsible trajectory steps and harness layers, consolidates recurring diagnoses into actionable flaw records, and maps them to scoped repair operators. Finally, HarnessFix generates and validates harness patches under flaw-specific repair specifications to reduce target flaws without introducing unacceptable regressions. We evaluate HarnessFix on SWE-Bench Verified, Terminal-Bench 2.0 Verified, GAIA and AppWorld. Across these benchmarks, HarnessFix improves held-out test performance over the initial harnesses by 15.2%--50.0%, outperforms human-designed and self-evolution baselines, and reveals recurring harness-flaw patterns across ETCLOVG layers.</p><hr><h2 id="key-findings" tabindex="-1">Key Findings <a class="header-anchor" href="#key-findings" aria-label="Permalink to &quot;Key Findings&quot;">​</a></h2><ul><li><strong>SWE-Bench Verified</strong>: 45→57 tasks solved (+26.7% relative improvement)</li><li><strong>Terminal-Bench 2.0</strong>: 6→9 tasks solved (+50.0% relative improvement)</li><li><strong>GAIA</strong>: 26→37 tasks solved (+42.3% relative improvement)</li><li><strong>AppWorld</strong>: 33→38 tasks solved (+15.2% relative improvement)</li><li>Outperforms prompt-evolution baselines (GEPA, SCOPE) by 5–10 tasks per benchmark</li><li>Exceeds strongest human-designed harnesses (Trae-Agent, MiroFlow, OpenCode, CUGA) on all four benchmarks</li><li>All four components (trace diagnosis, HTIR, scoped operators, regression checking) proved individually necessary — ablating any one loses 2–8 tasks</li></ul><h2 id="failure-diagnosis-repair-mechanism" tabindex="-1">Failure Diagnosis + Repair Mechanism <a class="header-anchor" href="#failure-diagnosis-repair-mechanism" aria-label="Permalink to &quot;Failure Diagnosis + Repair Mechanism&quot;">​</a></h2><p>HarnessFix uses four cooperating LLM agents operating in a pipeline:</p><ol><li><strong>Trace Abstraction</strong> — Converts heterogeneous agent execution logs into a unified &quot;Harness-aware Trace Intermediate Representation (HTIR)&quot; that captures step-level evidence, input provenance links, and control-flow relationships.</li><li><strong>Diagnosis</strong> — Attributes each failure to a specific execution step and maps it to an implicated harness layer using the ETCLOVG taxonomy: <strong>E</strong>xecution, <strong>T</strong>ool Interface, <strong>C</strong>ontext/Memory, <strong>L</strong>ifecycle, <strong>O</strong>bservability, <strong>V</strong>erification, <strong>G</strong>overnance.</li><li><strong>Repair</strong> — Maps diagnosed flaws to scoped repair operators (constrained modification templates organized by harness layer), generating flaw-specific repair specifications rather than generic patches.</li><li><strong>Validation</strong> — Tests each patch against a validation set, accepting only repairs that reduce target flaws while staying within regression bounds.</li></ol><p>Mapping to The Loop TEST/RECORD: the HTIR + ETCLOVG taxonomy operationalizes &quot;failure归因到層&quot; (attribute failure to layer) — the same discipline core.md TEST demands: &quot;失敗歸因到層，禁隨機修補&quot;. The validation gate directly implements the unverified_success閘門: patches are not accepted until mechanically verified against regression criteria.</p><h2 id="quantified-conditions" tabindex="-1">Quantified Conditions <a class="header-anchor" href="#quantified-conditions" aria-label="Permalink to &quot;Quantified Conditions&quot;">​</a></h2><ul><li>Improvement range: <strong>15.2%–50.0%</strong> relative task-count increase across four benchmarks (confirmed from fetched content)</li><li>Ablation cost of removing each component: 2–4 tasks (regression checking), 2–7 tasks (trace diagnosis), 3–8 tasks (scoped operators), 4–7 tasks (prompt-only repair)</li><li>Baseline comparison advantage vs. GEPA/SCOPE: <strong>5–10 tasks</strong> per benchmark</li><li>arXiv categories: not specified in fetched content</li></ul><h2 id="relevance-to-the-loop-failure-attribution" tabindex="-1">Relevance to The Loop (failure attribution) <a class="header-anchor" href="#relevance-to-the-loop-failure-attribution" aria-label="Permalink to &quot;Relevance to The Loop (failure attribution)&quot;">​</a></h2><p>HarnessFix directly instantiates The Loop&#39;s TEST/RECORD demand that failures be attributed to a specific layer before repair (&quot;失敗歸因到層，禁隨機修補&quot;). The ETCLOVG taxonomy provides a mechanical vocabulary for the RECORD phase&#39;s structured reflection — each failure maps to one of seven harness layers, preventing the &quot;random patching&quot; anti-pattern. The regression-checking validation gate mirrors the <code>unverified_success</code>閘門: no repair is promoted until an independent mechanical check confirms it reduces target flaws without introducing new regressions. The trace-to-HTIR abstraction step also models the OBSERVE principle — reading the full execution trace before diagnosing, not assuming truncated output is complete.</p>',16)])])}const u=a(s,[["render",t]]);export{h as __pageData,u as default};
